    step(D,R){if(d0&&D>d0)return adj?wbDayRecipe(R,adj):R;decay(D);flush(D);if(D<cfg.from)return R;const C=compute(R);mark(D,C.tg);adj=C.out;adjD=D;return wbDayRecipe(R,adj);},
