    if(!C){C=CHARS[K.key]={chip:K.chip,color:K.color,label:K.name,school:'',quiet:'',kid:1};const i=CHAR_ORDER.indexOf('Banker');CHAR_ORDER.splice(i>=0?i:CHAR_ORDER.length,0,K.key);n++;}
